def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_blender": And([
            self.blender_has_residue,
            Not(self.blender_clean),
            self.human_nearby,
            Not(self.robot_gripper_slip_resistant)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
